// v1b§4.1.1 source/2唯一字段序，FSL与经济历史嵌值共用；真实来源仍由S4 reader核验。
#pragma once
#include "growth_skill_qualification_v2.hpp"
#include "resident/checkpoint/codec_visitor.hpp"
#include <type_traits>
namespace hanmo::resident::growth_skill_qualification_codec {
template<class C>Status text(C& c,const char* name,StableId& value){c.field(name,value);if(c.status().ok&&(value.empty()||value.size()>256))return c.reject("InvalidSkillQualificationReference",name);return c.status();}
template<class C>Status ordinal(C& c,const char* name,Integer& value){c.field(name,value);if(c.status().ok&&value<1)return c.reject("InvalidSkillQualificationOrdinal",name);return c.status();}
template<class C>Status source(C& c,SourceRef& value){text(c,"domain",value.domain);text(c,"kind",value.kind);return text(c,"id",value.id);}
template<class C>Status moment(C& c,WorldMoment& value){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)(void)0;EncodedWorldMoment encoded;if(!c.reading()){auto result=encode_world_moment(value);if(!result.ok)return c.reject(result.error.original.code);encoded=std::move(result.value);}c.field("half_day_tick",encoded.half_day_tick);c.object("sub_half_day",[&](auto& x){x.field("numerator",encoded.sub_half_day.numerator);return x.field("denominator",encoded.sub_half_day.denominator);});if(c.reading()&&c.status().ok){auto result=decode_world_moment(encoded);if(!result.ok)return c.reject(result.error.original.code);value=std::move(result.value);}return c.status();}
template<class C>Status identity(C& c,WorldIdentity& value){CheckpointMemoryCharge temporary(0);StableId hex;if(!c.reading()){constexpr char digits[]="0123456789abcdef";hex.reserve(32);for(auto b:value.world_id){hex.push_back(digits[b>>4]);hex.push_back(digits[b&15]);}}c.field("world_id",hex);if(c.status().ok){if(hex.size()!=32)return c.reject("InvalidSkillQualificationWorld");for(std::size_t n=0;n<16;++n){const auto digit=[](char v)->int{return v>='0'&&v<='9'?v-'0':v>='a'&&v<='f'?v-'a'+10:-1;};auto a=digit(hex[n*2]),b=digit(hex[n*2+1]);if(a<0||b<0)return c.reject("InvalidSkillQualificationWorld");if(c.reading())value.world_id[n]=static_cast<std::uint8_t>(a*16+b);}}c.field("execution_epoch",value.execution_epoch);c.field("revision",value.revision);c.field("tick",value.tick);if(c.status().ok&&(value.execution_epoch<0||value.revision<0||value.tick<0))return c.reject("InvalidSkillQualificationIdentity");return c.status();}
template<class C>Status contribution(C& c,SkillContributionRefV2& value){Integer tag=static_cast<Integer>(value.index());c.field("tag",tag);if(c.status().ok&&(tag<0||tag>5))return c.reject("InvalidSkillContributionTag");if(!c.status().ok)return c.status();if(c.reading())switch(tag){case 0:value=StudyLessonResultRef{};break;case 1:value=StudyPerformanceAdjustmentRef{};break;case 2:value=LegacyCompletedStudyRef{};break;case 3:value=GroupLessonSkillContributionRef{};break;case 4:value=PracticeAwardSkillContributionRef{};break;case 5:value=VerifiedLegacyTradeGrantRef{};break;}
 return std::visit([&](auto& ref)->Status{using T=std::decay_t<decltype(ref)>;if constexpr(std::is_same_v<T,StudyLessonResultRef>||std::is_same_v<T,StudyPerformanceAdjustmentRef>){text(c,"action_id",ref.action_id);return ordinal(c,"lesson_ordinal",ref.lesson_ordinal);}else if constexpr(std::is_same_v<T,LegacyCompletedStudyRef>)return text(c,"action_id",ref.action_id);else if constexpr(std::is_same_v<T,GroupLessonSkillContributionRef>){text(c,"course_id",ref.course_id);ordinal(c,"period_ordinal",ref.period_ordinal);return text(c,"enrollment_id",ref.enrollment_id);}else if constexpr(std::is_same_v<T,PracticeAwardSkillContributionRef>){text(c,"award_id",ref.award_id);return text(c,"skill_id",ref.skill_id);}else return text(c,"original_trade_result_id",ref.original_trade_result_id);},value);
}
inline bool same_contribution(const SkillContributionRefV2& a,const SkillContributionRefV2& b){if(a.index()!=b.index())return false;return std::visit([&](const auto& x){using T=std::decay_t<decltype(x)>;const auto& y=std::get<T>(b);if constexpr(std::is_same_v<T,StudyLessonResultRef>||std::is_same_v<T,StudyPerformanceAdjustmentRef>)return x.action_id==y.action_id&&x.lesson_ordinal==y.lesson_ordinal;else if constexpr(std::is_same_v<T,LegacyCompletedStudyRef>)return x.action_id==y.action_id;else if constexpr(std::is_same_v<T,GroupLessonSkillContributionRef>)return x.course_id==y.course_id&&x.period_ordinal==y.period_ordinal&&x.enrollment_id==y.enrollment_id;else if constexpr(std::is_same_v<T,PracticeAwardSkillContributionRef>)return x.award_id==y.award_id&&x.skill_id==y.skill_id;else return x.original_trade_result_id==y.original_trade_result_id;},a);}
template<class C>Status fields(C& c,GrowthSkillQualificationV2& value){
 c.object("source_identity",[&](auto& x){return identity(x,value.source_identity);});text(c,"actor_id",value.actor_id);text(c,"skill_id",value.skill_id);text(c,"source_kind",value.source_kind);if(c.status().ok&&value.source_kind!="effective_initial_and_verified_permanent_contributions")return c.reject("InvalidSkillQualificationSourceKind");text(c,"origin_ref",value.origin_ref);
 c.object("actual_boundary_ref",[&](auto& x){x.object("original_source_ref",[&](auto& y){return source(y,value.actual_boundary_ref.original_source_ref);});return ordinal(x,"source_schema",value.actual_boundary_ref.source_schema);});c.object("observed_at",[&](auto& x){return moment(x,value.observed_at);});c.field("minimum_xp",value.minimum_xp);c.field("minimum_level",value.minimum_level);Integer coverage=static_cast<Integer>(value.coverage_kind);c.field("coverage_kind",coverage);if(c.status().ok&&(coverage<0||coverage>1||value.minimum_xp<0||value.minimum_xp>1200||value.minimum_level<0||value.minimum_level>4))return c.reject("InvalidSkillQualificationRange");if(c.reading()&&c.status().ok)value.coverage_kind=static_cast<GrowthSkillQualificationV2::Coverage>(coverage);
 std::size_t index=0;return c.sequence("contribution_refs",value.contribution_refs,[&](auto& x,auto& row){contribution(x,row);if(x.status().ok)for(std::size_t p=0;p<index;++p)if(same_contribution(value.contribution_refs[p],row))return x.reject("DuplicateSkillQualificationContribution");++index;return x.status();});
}
}
